import os, pypdf, openpyxl, docx

for root, dirs, files in os.walk('.'):
    for f in files:
        p = os.path.join(root, f)
        if f.endswith('.docx'):
            d = docx.Document(p)
            txt = ' '.join([para.text for para in d.paragraphs])
            if 'Kessler' in txt or 'Principal' in txt:
                print('DOCX match:', p)
        elif f.endswith('.pdf'):
            try:
                r = pypdf.PdfReader(p)
                for i, page in enumerate(r.pages):
                    t = page.extract_text() or ''
                    if 'Kessler' in t:
                        print('PDF match Kessler:', p, i)
            except:
                pass
        elif f.endswith('.xlsx'):
            try:
                wb = openpyxl.load_workbook(p, data_only=True)
                for s in wb.sheetnames:
                    ws = wb[s]
                    for row in ws.iter_rows(values_only=True):
                        row_str = ' '.join([str(v) for v in row if v is not None])
                        if 'Kessler' in row_str:
                            print('XLSX match Kessler:', p, s)
            except:
                pass
"
